        System.out.println("C2 : " + c2.replace("\n", "\\n").replace("\t", "\\t"));
        System.out.println("stable=" + c1.equals(c2));
    }

    @Test void probe() {
        Safelist sl = Safelist.relaxed().prescribeEntities(true);
        // also allow textarea for the probe
        sl.addTags("textarea");

        show("pre whitespace", "<pre>  a\tb\nc  </pre>", sl);
        show("code spaces", "<p>x</p><code>  a &amp; b  </code><p>y</p>", sl);
