        show("double entity", "<p>AT&amp;amp;T</p>", sl);
        show("script with safe markup", "<script><b>bold</b>alert(1)</script><p>hi</p>", sl);
        show("event attr", "<p onclick=\"steal()\" class=\"ok\">text</p>", sl);
        show("rejected wrapper", "<div onclick=x><p>one</p><p>two</p></div>", Safelist.none().addTags("p"));
        show("font wrapper inline", "<font color=red>abc</font>def", Safelist.none());
        show("nested rejected", "<table><tr><td onclick=x><b>cell</b></td></tr></table>", sl);
        show("malformed table", "<table><div><p>Para</p></div><tr><td>x</table><p>after</p>", sl);
        show("unclosed", "<p>para <a href=\"/x\">link<code>code", sl);
        show("empty", "", sl);
