package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

class Probe2Test {

    static int failures = 0;
    static void check(String label, String input, Safelist sl, String baseUri) {
        String c1 = baseUri == null ? Jsoup.clean(input, sl) : Jsoup.clean(input, baseUri, sl);
        String c2 = Jsoup.clean(c1, sl);
        boolean ok = c1.equals(c2);
        // also structural reparse
        Document d1 = Jsoup.parseBodyFragment(c1);
        Document d2 = Jsoup.parseBodyFragment(c2);
        boolean struct = d1.body().html().equals(d2.body().html());
        if (!ok || !struct) {
            failures++;
            System.out.println("FAIL " + label + " idempotent=" + ok + " struct=" + struct);
            System.out.println("  IN : " + input.replace("\n", "\\n").replace("\t", "\\t"));
            System.out.println("  C1 : " + c1.replace("\n", "\\n").replace("\t", "\\t"));
            System.out.println("  C2 : " + c2.replace("\n", "\\n").replace("\t", "\\t"));
        }
    }

    @Test void probe() {
        // srcset / imagesrcset candidate resolution with base URI
        Safelist img = Safelist.none().addTags("img").addAttributes("img", "src", "srcset", "imagesrcset", "alt");
        check("srcset rel", "<img srcset=\"a.jpg 1x, b.jpg 2x\">", img, "https://example.com/p/");
        check("srcset abs", "<img srcset=\"https://example.com/p/a.jpg 1x\">", img, "https://example.com/p/");
        check("srcset mixed", "<img srcset=\"/a.jpg 1x, https://e.com/b.png 2x\">", img, "https://example.com/p/");
        check("srcset trailing comma", "<img srcset=\"a.jpg,\">", img, "https://example.com/");
        check("srcset tab nl", "<img srcset=\"\ta.jpg\n1x,\nb.jpg 2x\">", img, "https://example.com/");
        check("srcset no base", "<img srcset=\"a.jpg 1x\">", img, null);
        check("srcset comma in filename", "<img srcset=\"photo1,2.jpg 1x\">", img, "https://example.com/");
        check("srcset query comma", "<img srcset=\"/s?q=1,2 1x\">", img, "https://example.com/");
        check("imagesrcset", "<link imagesrcset=\"/a.png 1x\">", img, "https://example.com/");

        // protocol enforcement edge cases
        Safelist a = Safelist.none().addTags("a").addAttributes("a", "href");
        Safelist http = a.copy().addProtocols("a", "href", "http", "https");
        check("uppercase scheme", "<a href=\"HTTPS://e.com/\">x</a>", http, "https://example.com/");
        check("pct scheme", "<a href=\"java%73cript:alert(1)\">x</a>", http, "https://example.com/");
        check("backslashes", "<a href=\"\\\\javascript:alert(1)\">x</a>", http, "https://example.com/");
        check("tab in scheme", "<a href=\"java\tscript:alert(1)\">x</a>", http, "https://example.com/");
        check("rel with colon", "<a href=\"/foo:bar\">x</a>", http, "https://example.com/");
        check("relative 123", "<a href=\"a/b:c\">x</a>", http, "https://example.com/");
        check("anchor", "<a href=\"#x\">x</a>", http, "https://example.com/");
        check("rel empty base", "<a href=\"/foo:bar\">x</a>", http, null);
        check("leading ws url", "<a href=\"  https://e.com/\">x</a>", http, "https://example.com/");
        check("del in scheme", "<a href=\"java\x7fscript:alert(1)\">x</a>", http, "https://example.com/");
        check("zwsp", "<a href=\"java\u200bscript:alert(1)\">x</a>", http, "https://example.com/");
        check("srcset smuggled", "<img srcset=\"/a.jpg 1x, javascript:alert(1) 2x\">", img, "https://example.com/");

        Safelist anchor = Safelist.none().addTags("a").addAttributes("a", "href").addProtocols("a", "href", "#");
        check("hash only", "<a href=\"#top\">x</a>", anchor, null);
        check("http vs hash", "<a href=\"https://e.com\">x</a>", anchor, null);

        // whitespace / structure edge cases
        Safelist blocks = Safelist.none().addTags("p", "b", "i", "pre", "code", "textarea", "div", "table", "tbody", "tr", "td", "h1", "a", "font");
        check("code inline lead", "foo <code>  a  </code> bar", blocks, null);
        check("code block lead", "<p>x</p><code>  a  </code><p>y</p>", blocks, null);
        check("pre tab", "<pre>\n\t  x  \t\n</pre>", blocks, null);
        check("pre entities", "<pre>&amp;amp; &lt;b&gt;\n  </pre>", blocks, null);
        check("textarea nl", "<textarea>x\n\n  y</textarea>", blocks, null);
        check("double wrapper", "<font><center><p>a</p>text<p>b</p></center></font>", blocks, null);
        check("rejected table wrapper", "<font><table><tr><td>x</td></tr></table></font>", blocks, null);
        check("fostered form", "<form><table><input name=x value=1><tr><td>y</td></tr></table></form>", blocks, null);
        check("deep nested reject", "<div><div><div><p>ok</p></div></div></div>", blocks, null);
        check("text between blocks", "<h1>A</h1>B<p>C</p>D", blocks, null);
        check("hoisted text spaces", "<p>a</p><font> x </font><p>b</p>", blocks, null);
        check("adjacent links", "<a href='/'>x</a><a href='/'>y</a>", blocks, null);
        check("b i text", "<b>1</b><i>2</i>3", blocks, null);
        check("empty pre", "<pre></pre>", blocks, null);
        check("pre only spaces", "<pre>   </pre>", blocks, null);
        check("malformed open", "<<<div>>><p>x", blocks, null);
        check("unclosed tags", "<div><p>text<b>bold", blocks, null);
        check("table fragments", "<table><tr><td>a<td>b</table>after", blocks, null);
        check("script fake markup", "<script><b>x</b></script><p>y</p>", blocks, null);
        check("style fake", "<style><b>x</b></style><p>y</p>", blocks, null);
        check("textarea fake", "<textarea><b>x</b></textarea><p>y</p>", blocks, null);
        check("event attr", "<p onclick=x class=y>a<b onclick=z>b</b></p>", blocks, null);
        check("nbsp", "<p>a&nbsp;&nbsp;b</p>", blocks, null);
        check("null bytes", "<p>a\x00b</p>", blocks, null);

        System.out.println("TOTAL FAILURES: " + failures);
        if (failures > 0) throw new AssertionError(failures + " failures");
    }
}

