1	package org.jsoup.nodes;
2	
3	import org.jsoup.internal.QuietAppendable;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.nodes.Document.OutputSettings;
6	import org.jsoup.parser.Tag;
7	import org.jsoup.select.NodeVisitor;
8	import org.jspecify.annotations.Nullable;
9	
10	/** Base Printer */
11	class Printer implements NodeVisitor {
12	    final Node root;
13	    final QuietAppendable accum;
14	    final OutputSettings settings;
15	
16	    Printer(Node root, QuietAppendable accum, OutputSettings settings) {
17	        this.root = root;
18	        this.accum = accum;
19	        this.settings = settings;
20	    }
21	
22	    void addHead(Element el, int depth) {
23	        el.outerHtmlHead(accum, settings);
24	    }
25	
26	    void addTail(Element el, int depth) {
27	        el.outerHtmlTail(accum, settings);
28	    }
29	
30	    void addText(TextNode textNode, int textOptions, int depth) {
31	        int options = Entities.ForText | textOptions;
32	        Entities.escape(accum, textNode.coreValue(), settings, options);
33	    }
34	
35	    void addNode(LeafNode node, int depth) {
36	        node.outerHtmlHead(accum, settings);
37	    }
38	
39	    void indent(int depth) {
40	        accum.append('\n').append(StringUtil.padding(depth * settings.indentAmount(), settings.maxPaddingWidth()));
41	    }
42	
43	    @Override
44	    public void head(Node node, int depth) {
45	        if (node.getClass() == TextNode.class)  addText((TextNode) node, 0, depth); // Excludes CData; falls to addNode
46	        else if (node instanceof Element)       addHead((Element) node, depth);
47	        else                                    addNode((LeafNode) node, depth);
48	    }
49	
50	    @Override
51	    public void tail(Node node, int depth) {
52	        if (node instanceof Element) { // otherwise a LeafNode
53	            addTail((Element) node, depth);
54	        }
55	    }
56	
57	    /** Pretty Printer */
58	    static class Pretty extends Printer {
59	        boolean preserveWhitespace = false;
60	
61	        Pretty(Node root, QuietAppendable accum, OutputSettings settings) {
62	            super(root, accum, settings);
63	
64	            // check if there is a pre on stack
65	            for (Node node = root; node != null; node = node.parentNode()) {
66	                if (tagIs(Tag.PreserveWhitespace, node)) {
67	                    preserveWhitespace = true;
68	                    break;
69	                }
70	            }
71	        }
72	
73	        @Override
74	        void addHead(Element el, int depth) {
75	            if (shouldIndent(el))
76	                indent(depth);
77	            super.addHead(el, depth);
78	            if (tagIs(Tag.PreserveWhitespace, el)) preserveWhitespace = true;
79	        }
80	
81	        @Override
82	        void addTail(Element el, int depth) {
83	            if (shouldIndent(nextNonBlank(el.firstChild()))) {
84	                indent(depth);
85	            }
86	            super.addTail(el, depth);
87	
88	            // clear the preserveWhitespace if this element is not, and there are none on the stack above
89	            if (preserveWhitespace && el.tag.is(Tag.PreserveWhitespace)) {
90	                for (Element parent = el.parent(); parent != null; parent = parent.parent()) {
91	                    if (parent.tag().preserveWhitespace()) return; // keep
92	                }
93	                preserveWhitespace = false;
94	            }
95	        }
96	
97	        @Override
98	        void addNode(LeafNode node, int depth) {
99	            if (shouldIndent(node))
100	                indent(depth);
101	            super.addNode(node, depth);
102	        }
103	
104	        @Override
105	        void addText(TextNode node, int textOptions, int depth) {
106	            if (!preserveWhitespace) {
107	                textOptions |= Entities.Normalise;
108	                textOptions = textTrim(node, textOptions);
109	
110	                if (!node.isBlank() && isBlockEl(node.parentNode) && shouldIndent(node))
111	                    indent(depth);
112	            }
113	
114	            super.addText(node, textOptions, depth);
115	        }
116	
117	        int textTrim(TextNode node, int options) {
118	            if (!isBlockEl(node.parentNode)) return options; // don't trim inline, whitespace significant
119	            Node prev = node.previousSibling();
120	            Node next = node.nextSibling();
121	
122	            // if previous is not an inline element
123	            if (!(prev instanceof Element && !isBlockEl(prev))) {
124	                // if there is no previous sib; or not a text node and should be indented. The previous sibling is
125	                // judged on its own layout, so the traversal root exemption does not apply: when serializing an
126	                // element's inner HTML that root is just the first of several siblings being printed, and treating
127	                // it specially would leave a leading newline on following text untrimmed, which would re-parse as
128	                // an extra space and make the output non-idempotent.
129	                if (prev == null || !(prev instanceof TextNode) && shouldIndent(prev, false))
130	                    options |= Entities.TrimLeading;
131	            }
132	
133	            if (next == null || !(next instanceof TextNode) && shouldIndent(next)) {
134	                options |= Entities.TrimTrailing;
135	            } else { // trim trailing whitespace if the next non-empty TextNode has leading whitespace
136	                next = nextNonBlank(next);
137	                if (next instanceof TextNode && StringUtil.isWhitespace(next.nodeValue().codePointAt(0)))
138	                    options |= Entities.TrimTrailing;
139	            }
140	
141	            return options;
142	        }
143	
144	        final boolean shouldIndent(@Nullable Node node) {
145	            return shouldIndent(node, true);
146	        }
147	
148	        boolean shouldIndent(@Nullable Node node, boolean honorRoot) {
149	            if (node == null || honorRoot && node == root || preserveWhitespace || isBlankText(node))
150	                return false;
151	            if (isBlockEl(node))
152	                return true;
153	
154	            Node prevSib = previousNonblank(node);
155	            if (isBlockEl(prevSib)) return true;
156	
157	            Element parent = node.parentNode;
158	            if (!isBlockEl(parent) || parent.tag().is(Tag.InlineContainer) || !hasNonTextNodes(parent))
159	                return false;
160	
161	            return prevSib == null ||
162	                (!(prevSib instanceof TextNode) &&
163	                    (isBlockEl(prevSib) || !(prevSib instanceof Element)));
164	        }
165	
166	        boolean isBlockEl(@Nullable Node node) {
167	            if (node == null) return false;
168	            if (node instanceof Element) {
169	                Element el = (Element) node;
170	                if (el.nameIs("br")) return true; // give <br> a newline; actually an inline tag
171	                return el.isBlock() ||
172	                    (!el.tag.isKnownTag() && (el.parentNode instanceof Document || hasChildBlocks(el)));
173	            }
174	
175	            return false;
176	        }
177	
178	        /**
179	         Returns true if any of the Element's child nodes should indent. Checks the last 5 nodes only (to minimize
180	         scans).
181	         */
182	        static boolean hasChildBlocks(Element el) {
183	            Element child = el.firstElementChild();
184	            for (int i = 0; i < maxScan && child != null; i++) {
185	                if (child.isBlock() || !child.tag.isKnownTag()) return true;
186	                child = child.nextElementSibling();
187	            }
188	            return false;
189	        }
190	        static private final int maxScan = 5;
191	
192	        static boolean hasNonTextNodes(Element el) {
193	            Node child = el.firstChild();
194	            for (int i = 0; i < maxScan && child != null; i++) {
195	                if (!(child instanceof TextNode)) return true;
196	                child = child.nextSibling();
197	            }
198	            return false;
199	        }
200	
201	        static @Nullable Node previousNonblank(Node node) {
202	            Node prev = node.previousSibling();
203	            while (isBlankText(prev)) prev = prev.previousSibling();
204	            return prev;
205	        }
206	
207	        static @Nullable Node nextNonBlank(@Nullable Node node) {
208	            while (isBlankText(node)) node = node.nextSibling();
209	            return node;
210	        }
211	
212	        static boolean isBlankText(@Nullable Node node) {
213	            return node instanceof TextNode && ((TextNode) node).isBlank();
214	        }
215	
216	        static boolean tagIs(int option, @Nullable Node node) {
217	            return node instanceof Element && ((Element) node).tag.is(option);
218	        }
219	    }
220	
221	    /** Outline Printer */
222	    static class Outline extends Pretty {
223	        Outline(Node root, QuietAppendable accum, OutputSettings settings) {
224	            super(root, accum, settings);
225	        }
226	
227	        @Override
228	        boolean isBlockEl(@Nullable Node node) {
229	            return node != null;
230	        }
231	
232	        @Override
233	        boolean shouldIndent(@Nullable Node node, boolean honorRoot) {
234	            if (node == null || honorRoot && node == root || preserveWhitespace || isBlankText(node))
235	                return false;
236	            if (node instanceof TextNode) {
237	                return node.previousSibling() != null || node.nextSibling() != null;
238	            }
239	            return true;
240	        }
241	    }
242	
243	    static Printer printerFor(Node root, QuietAppendable accum) {
244	        OutputSettings settings = NodeUtils.outputSettings(root);
245	        if (settings.outline())     return new Printer.Outline(root, accum, settings);
246	        if (settings.prettyPrint()) return new Printer.Pretty(root, accum, settings);
247	        return new Printer(root, accum, settings);
248	    }
249	}
