package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

class FuzzTest {
    static final String[] TAGS = {"p","b","i","pre","code","textarea","div","font","center","a","table","tbody","tr","td","h1","span","script","style","img","br","u","em","strong"};
    static final String[] TEXTS = {"x", " ", "  ", "\n", "\t", " a", "a ", " a ", "&amp;", "&amp;amp;", "&lt;b&gt;", "a&nbsp;b", "", "word", "\n\t ", "&#65;"};
    static final String[] ATTRS = {"onclick='x()'", "class='c'", "href='/x'", "href='javascript:x'", "href='\t/java%73cript:x'", "srcset='a.jpg 1x, b 2x'", "title='t'", "id='i'"};

    static String randText(Random r) {
        StringBuilder sb = new StringBuilder();
        int n = r.nextInt(4);
        for (int i = 0; i < n; i++) sb.append(TEXTS[r.nextInt(TEXTS.length)]);
        return sb.toString();
    }

    static String gen(Random r, int depth) {
        StringBuilder sb = new StringBuilder();
        int kids = r.nextInt(5);
        for (int k = 0; k < kids; k++) {
            int choice = r.nextInt(10);
            if (choice < 4 || depth > 4) {
                sb.append(randText(r));
            } else {
                String tag = TAGS[r.nextInt(TAGS.length)];
                sb.append("<").append(tag);
                if (r.nextBoolean()) {
                    int na = r.nextInt(2);
                    for (int a = 0; a < na; a++) sb.append(" ").append(ATTRS[r.nextInt(ATTRS.length)]);
                }
                if (tag.equals("img") || tag.equals("br")) { sb.append(">"); continue; }
                sb.append(">");
                sb.append(gen(r, depth + 1));
                // sometimes omit close tag
                if (r.nextInt(7) != 0) sb.append("</").append(tag).append(">");
            }
        }
        return sb.toString();
    }

    static String visibleText(String html) {
        Document d = Jsoup.parseBodyFragment(html);
        StringBuilder sb = new StringBuilder();
        appendText(d.body(), sb);
        return sb.toString();
    }
    static void appendText(Node n, StringBuilder sb) {
        for (Node c : n.childNodes()) {
            if (c instanceof TextNode) sb.append(((TextNode) c).getWholeText());
            else appendText(c, sb);
        }
    }

    @Test void fuzz() {
        Safelist sl = Safelist.none()
            .addTags("p","b","i","pre","code","textarea","div","table","tbody","tr","td","h1","a","u","em","strong","img","br")
            .addAttributes("a","href","title").addAttributes("img","srcset","src","alt","title")
            .addAttributes("p","class","title").addAttributes(":all","class");
        int fails = 0;
        Random r = new Random(1234);
        for (int it = 0; it < 200000; it++) {
            String in = gen(r, 0);
            String c1, c2;
            try { c1 = Jsoup.clean(in, sl); } catch (Exception e) {
                if (++fails <= 30) System.out.println("EX1 " + e + " IN=" + encode(in));
                continue;
            }
            try { c2 = Jsoup.clean(c1, sl); } catch (Exception e) {
                if (++fails <= 30) System.out.println("EX2 " + e + " IN=" + encode(in) + " C1=" + encode(c1));
                continue;
            }
            if (!c1.equals(c2)) {
                if (++fails <= 30) {
                    System.out.println("IDEMPOTENT FAIL");
                    System.out.println("  IN=" + encode(in));
                    System.out.println("  C1=" + encode(c1));
                    System.out.println("  C2=" + encode(c2));
                }
                continue;
            }
            // safety: no event attrs / scripts
            String lc = c1.toLowerCase();
            if (lc.contains("<script") || lc.contains("onclick") || lc.contains("javascript:")) {
                if (++fails <= 30) System.out.println("SAFETY FAIL C1=" + encode(c1) + " IN=" + encode(in));
            }
            // structure stable after reparse+serialize
            String rs = Jsoup.parseBodyFragment(c1).body().html();
            if (!rs.equals(c1) && !rs.equals(c1.replace("\n", ""))) {
                // check via clean again which already passed; instead compare reparsed text
                String t1 = visibleText(c1), t2 = visibleText(rs);
                if (!t1.equals(t2)) {
                    if (++fails <= 30) {
                        System.out.println("REPARSE-TEXT FAIL IN=" + encode(in));
                        System.out.println("  C1=" + encode(c1));
                        System.out.println("  RS=" + encode(rs));
                    }
                }
            }
        }
        System.out.println("FUZZ DONE, fails=" + fails);
        if (fails > 0) throw new AssertionError(fails + " fuzz failures");
    }

    static String encode(String s) {
        return s.replace("\\", "\\\\").replace("\n", "\\n").replace("\t", "\\t").replace("\r", "\\r");
    }
}

