    static final String[] TEXTS = {"x", " ", "  ", "\n", "\t", " a", "a ", " a ", "&amp;", "&amp;amp;", "&lt;b&gt;", "a&nbsp;b", "", "word", "\n\t ", "&#65;"};
    static final String[] ATTRS = {"onclick='x()'", "class='c'", "href='/x'", "href='javascript:x'", "href='\t/java%73cript:x'", "srcset='a.jpg 1x, b 2x'", "title='t'", "id='i'"};
    static String randText(Random r) { StringBuilder sb=new StringBuilder(); int n=r.nextInt(4); for(int i=0;i<n;i++) sb.append(TEXTS[r.nextInt(TEXTS.length)]); return sb.toString(); }
    static String gen(Random r, int depth) {
        StringBuilder sb = new StringBuilder(); int kids = r.nextInt(5);
        for (int k=0;k<kids;k++) { int choice=r.nextInt(10);
            if (choice<4||depth>4) sb.append(randText(r));
            else { String tag=TAGS[r.nextInt(TAGS.length)]; sb.append("<").append(tag);
                if (r.nextBoolean()){int na=r.nextInt(2); for(int a=0;a<na;a++) sb.append(" ").append(ATTRS[r.nextInt(ATTRS.length)]);}
                if (tag.equals("img")||tag.equals("br")){sb.append(">");continue;}
                sb.append(">"); sb.append(gen(r,depth+1));
                if (r.nextInt(7)!=0) sb.append("</").append(tag).append(">");
            }
        } return sb.toString();
    }
    public static void main(String[] args) {
        Safelist sl = Safelist.none().addTags("p","b","i","pre","code","textarea","div","table","tbody","tr","td","h1","a","u","em","strong","img","br")
