            if(c<7){ String t=BLOCK[R.nextInt(BLOCK.length)];
                if(t.equals("table")){ if(R.nextBoolean()){sb.append("<table>");} else {sb.append("<table><tr><td>");}
                    inline(sb,0); sb.append(R.nextBoolean()?"</table>":"</td></tr></table>");
                    if(R.nextBoolean()) sb.append(txt());
                    continue; }
                sb.append("<").append(t); if(R.nextInt(4)==0) sb.append(" ").append(ATTRS[R.nextInt(ATTRS.length)]); sb.append(">");
                if(t.equals("pre")) sb.append(txt()); else inline(sb,0);
                if(R.nextInt(8)!=0) sb.append("</").append(t).append(">");
            } else inline(sb,0);
            if(R.nextBoolean()) sb.append(txt());
        }
        return sb.toString();
    }
