        Random meta=new Random(seed);
        for(int it=0;it<100000;it++){
            R=new Random(meta.nextLong()); String in=gen();
            boolean tBad,uBad;
            try{ String c1=Jsoup.clean(in,sl), c2=Jsoup.clean(c1,sl); tBad=!c1.equals(c2);}catch(Exception e){tBad=true;}
            String u1=runUp(in,sl), u2=runUp(u1,sl); uBad=!u1.equals(u2);
            if(tBad&&!uBad){ if(taskOnly<25) System.out.println("TASK-ONLY IN="+enc(in)); taskOnly++; }
