import java.nio.file.*;
import java.util.*;
public class ContentDiff {
    static String dec(String s){StringBuilder b=new StringBuilder();
        for(int i=0;i<s.length();i++){char c=s.charAt(i);
            if(c=='\\'&&i+1<s.length()){char n=s.charAt(++i);if(n=='n')b.append('\n');else if(n=='t')b.append('\t');else if(n=='r')b.append('\r');else b.append(n);}else b.append(c);}
        return b.toString();}
    static String vis(String html){
        Document d=Jsoup.parseBodyFragment(html);
        StringBuilder sb=new StringBuilder();
        walk(d.body(),sb);
        return sb.toString().replaceAll("[ \t\n\r\f]+"," ");
    }
    static void walk(Node n,StringBuilder sb){
        for(Node c:n.childNodes()){
            if(c instanceof TextNode) sb.append(((TextNode)c).getWholeText());
            else if(c instanceof Element) walk(c,sb);
        }
    }
    public static void main(String[] a) throws Exception {
        Safelist sl=Safelist.none().addTags("p","div","h1","pre","code","textarea","table","tbody","tr","td","b","i","a","font","span","u")
            .addAttributes("a","href","title").addAttributes(":all","class","title","id");
        List<String> lines=Files.readAllLines(Paths.get(a[0]));
        int diff=0;
        for(int i=0;i<lines.size();i++){
            String in=dec(lines.get(i));
