import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Safelist;
public class FinalSpec {
    static int fail=0;
    static void ck(boolean ok,String m){ if(!ok){fail++;System.out.println("FAIL "+m);} }
    public static void main(String[] x){
        Safelist sl = Safelist.relaxed().addTags("textarea");
        // 1 pre/code/textarea whitespace + entities survive clean->serialize->reparse
        for(String in: new String[]{
            "<pre>  a\tb\nc  </pre>","<pre>if (a &lt; b && b &gt; c) {}</pre>",
            "<textarea>a &amp; b\n  c&lt;d</textarea>","<p>AT&amp;amp;T</p>"}){
            String c1=Jsoup.clean(in,sl); Document d=Jsoup.parse(c1); String rp=d.body().html(); String c2=Jsoup.clean(c1,sl);
            ck(c1.equals(c2),"idempotent "+in); ck(c1.equals(rp),"reparse-equal "+in);
        }
        // 2 script content text-only; events removed; safe siblings kept in order
        String s=Jsoup.clean("<script><b>bold</b>alert(1)</script><p onclick=x>hi</p>",sl);
        ck(!s.toLowerCase().contains("script")&&!s.contains("onclick")&&s.contains("hi"),"script/events "+s);
        // 3 hoisting order preserved once
        Safelist p=Safelist.none().addTags("p","b");
        ck(Jsoup.clean("<div onclick=x><p>one</p><p>two</p></div>",p).replaceAll("\\s","")
            .equals("<p>one</p><p>two</p>"),"hoist order");
        ck(Jsoup.clean("a<script>x</script>b",p).equals("ab"),"text once in order");
        // 4 adjacent blocks distinguishable, inline adds no char
        ck(Jsoup.clean("<h1>A</h1><p>B</p>",p).replace("\n","").equals("<h1>A</h1><p>B</p>"),"block boundary");
        // 5 malformed/table reparseable
        String t=Jsoup.clean("<table><div><p>Para</p></div><tr><td>x</table><p>after</p>",
            sl.addTags("div"));
        ck(Jsoup.clean(t,sl).equals(t),"malformed table idempotent");
        // 6 empty/all-rejected/malformed no exception + consistent
        for(String in:new String[]{"","   ","<script>x</script><style>y</style>","</div></tr><<<>>>"}){
            String c=Jsoup.clean(in,p); ck(Jsoup.clean(c,p).equals(c),"empty/rej stable ["+in+"]");
        }
        // 7 repeated independent calls identical; different safelists don't pollute
        String i="<p onclick=z>a</p>";
        ck(Jsoup.clean(i,p).equals(Jsoup.clean(i,p)),"repeat identical");
        ck(Jsoup.clean(i,Safelist.none().addTags("p","b")).equals(Jsoup.clean(i,p)),"safelist isolation");
        System.out.println(fail==0?"ALL SPEC CHECKS PASS":fail+" FAILURES");
        if(fail>0) System.exit(1);
    }
